Clase Caja
    Publico Definir contenido Como Entero;
FinClase

Proceso ProbarCopiaIndependiente
    Definir valorInicial Como Entero;
    Definir valorNuevo Como Entero;
    Definir original Como Caja;
    Definir copia Como Caja;
    Leer valorInicial;
    Leer valorNuevo;
    original <- Nuevo Caja();
    original.contenido <- valorInicial;
    copia <- Copiar(original);
    copia.contenido <- valorNuevo;
    Escribir original.contenido;
FinProceso
